"use strict";

const tiers = APP_CONFIG.tiers.map((e) => ({ ...e }));
let unlocked = !1,
  deferredInstallPrompt = null;
const MAX_LOG_ENTRIES = 20;

function logClientError(e, t) {
  try {
    const n = APP_CONFIG.storageKeys.errorLog,
      r = JSON.parse(localStorage.getItem(n) || "[]");
    r.push({
      message: String(e),
      context: t || "unknown",
      time: new Date().toISOString(),
      version: APP_CONFIG.version,
    });
    const a = r.slice(-MAX_LOG_ENTRIES);
    localStorage.setItem(n, JSON.stringify(a));
  } catch (e) {}
}

window.addEventListener("error", (e) => {
  logClientError(
    e.message,
    e.filename ? `${e.filename}:${e.lineno}` : "global"
  );
});

const DEFAULT_SETTINGS = { theme: null, tariffOverride: null };

function loadSettings() {
  try {
    const e = localStorage.getItem(APP_CONFIG.storageKeys.settings);
    return e ? { ...DEFAULT_SETTINGS, ...JSON.parse(e) } : { ...DEFAULT_SETTINGS };
  } catch (e) {
    return logClientError(e.message, "loadSettings"), { ...DEFAULT_SETTINGS };
  }
}

function saveSettings(e) {
  try {
    localStorage.setItem(APP_CONFIG.storageKeys.settings, JSON.stringify(e));
  } catch (e) {
    logClientError(e.message, "saveSettings");
  }
}

function updateSetting(e, t) {
  const n = loadSettings();
  (n[e] = t), saveSettings(n);
}

function sanitizeNumber(e, t = 0) {
  const n = parseFloat(e);
  return Number.isNaN(n) || !Number.isFinite(n) || n < 0 ? t : n;
}

/* تصحيح دالة حساب التكلفة بناءً على المقطوعية المباشرة */
function costFor(e, t) {
  if (e <= 0) return 0;
  
  // إذا كان الاستهلاك ضمن المقطوعية الثابتة (0-6)
  const firstTier = tiers[0];
  if (firstTier && firstTier.flat && e <= firstTier.upTo) {
    return firstTier[t];
  }

  let n = 0, r = 0;
  for (const a of tiers) {
    const o = a.upTo;
    if (a.flat) {
      r = o; // التجاوز عن الشريحة المقطوعة عند تخطيها
      continue;
    }
    if (e > r) {
      n += (Math.min(e, o) - r) * a[t];
    }
    r = o;
    if (e <= o) break;
  }
  return n;
}

function renderTariffTable() {
  document.querySelector("#tariffTable tbody").innerHTML = tiers
    .map(
      (e, t) => `
    <tr>
      <td>${e.label}</td>
      <td><input type="number" step="0.01" value="${e.water}" data-i="${t}" data-f="water" oninput="onTariffEdit(this)" readonly aria-label="سعر المياه للشريحة ${e.label}"></td>
      <td><input type="number" step="0.01" value="${e.sewage}" data-i="${t}" data-f="sewage" oninput="onTariffEdit(this)" readonly aria-label="سعر الصرف الصحي للشريحة ${e.label}"></td>
    </tr>`
    )
    .join("");
}

function onTariffEdit(e) {
  const t = +e.dataset.i,
    n = e.dataset.f;
  (tiers[t][n] = sanitizeNumber(e.value, tiers[t][n])),
    updateSetting("tariffOverride", tiers),
    calcAll();
}

function calcAll() {
  const e = sanitizeNumber(document.getElementById("consumption").value, 0),
    t = costFor(e, "water"),
    n = costFor(e, "sewage"),
    r = t + n;

  document.getElementById("waterOut").textContent = `${t.toFixed(2)} ${APP_CONFIG.currencyLabelAr[0]}`;
  document.getElementById("sewageOut").textContent = `${n.toFixed(2)} ${APP_CONFIG.currencyLabelAr[0]}`;
  document.getElementById("totalOut").textContent = `${r.toFixed(2)} ${APP_CONFIG.currencyLabelAr}`;

  const a = costFor(e + 1, "water") - t + (costFor(e + 1, "sewage") - n);
  
  /* تصحيح رقم المتر القادم عند الإدخال بالكسور */
  const nextMeterNum = Math.floor(e) + 1;
  document.getElementById("marginalHint").textContent = `المتر القادم (رقم ${nextMeterNum}) سيكلفك تقريباً ${a.toFixed(2)} ${APP_CONFIG.currencyLabelAr} إضافية.`;

  const o = document.getElementById("statusBadge");
  o.innerHTML =
    e <= 18
      ? '<span class="badge ok">ضمن نطاق استهلاك منزلي معتدل</span>'
      : e <= 24
      ? '<span class="badge warn">استهلاك متوسط-مرتفع - تحقق من السبب</span>'
      : '<span class="badge bad">استهلاك مرتفع - راجع التسريبات وأسباب الزيادة</span>';

  const s =
    sanitizeNumber(document.getElementById("tankerPrice").value, APP_CONFIG.defaultTankerPrice) /
    (sanitizeNumber(document.getElementById("tankerQty").value, APP_CONFIG.defaultTankerQty) || 1);

  document.getElementById("networkMarginal").textContent = `${a.toFixed(2)} ${APP_CONFIG.currencyLabelAr[0]}`;
  document.getElementById("tankerMarginal").textContent = `${s.toFixed(2)} ${APP_CONFIG.currencyLabelAr[0]}`;

  const i = document.getElementById("boxNetwork"),
    l = document.getElementById("boxTanker");
  i.classList.remove("win"), l.classList.remove("win");

  const c = document.getElementById("recommendHint");
  if (a < s) {
    i.classList.add("win");
    c.textContent = "الأوفر: سحب المتر الإضافي من العداد بدل طلب صهريج مياه.";
  } else {
    l.classList.add("win");
    c.textContent = "الأوفر هنا: صهريج المياه أرخص من تجاوز الشريحة الحالية.";
  }
}

function toggleLock() {
  const e = document.querySelectorAll("#tariffTable input"),
    t = document.getElementById("lockToggle"),
    n = document.getElementById("lockLabel");

  if (unlocked) {
    (unlocked = !1),
      e.forEach((e) => e.setAttribute("readonly", !0)),
      (n.textContent = "تعديل"),
      t.setAttribute("aria-pressed", "false");
  } else {
    const r = prompt("أدخل الرمز السري لتعديل الأسعار:");
    r === APP_CONFIG.editPin
      ? ((unlocked = !0),
        e.forEach((e) => e.removeAttribute("readonly")),
        (n.textContent = "قفل"),
        t.setAttribute("aria-pressed", "true"))
      : null !== r && alert("الرمز غير صحيح.");
  }
}

function toggleTheme() {
  const e = document.documentElement,
    t = loadSettings(),
    n = window.matchMedia("(prefers-color-scheme: dark)").matches,
    r = (t.theme ? "dark" === t.theme : n) ? "light" : "dark";

  e.setAttribute("data-theme", r),
    updateSetting("theme", r),
    document.getElementById("themeToggle").setAttribute("aria-pressed", String("dark" === r));
}

function exportSettings() {
  try {
    const e = loadSettings(),
      t = {
        app: APP_CONFIG.appName,
        version: APP_CONFIG.version,
        exportedAt: new Date().toISOString(),
        settings: e,
      },
      n = new Blob([JSON.stringify(t, null, 2)], { type: "application/json" }),
      r = URL.createObjectURL(n),
      a = document.createElement("a");

    (a.href = r),
      (a.download = "aquabill-settings.json"),
      document.body.appendChild(a),
      a.click(),
      a.remove(),
      URL.revokeObjectURL(r);
  } catch (e) {
    logClientError(e.message, "exportSettings"), alert("تعذّر تصدير الإعدادات.");
  }
}

function importSettings(e) {
  const t = e.target.files && e.target.files[0];
  if (!t) return;
  const n = new FileReader();
  (n.onload = () => {
    try {
      const e = JSON.parse(n.result),
        t = { ...DEFAULT_SETTINGS, ...(e.settings || {}) };
      saveSettings(t),
        t.theme && document.documentElement.setAttribute("data-theme", t.theme),
        Array.isArray(t.tariffOverride) &&
          t.tariffOverride.length === tiers.length &&
          (t.tariffOverride.forEach((e, t) => {
            (tiers[t].water = sanitizeNumber(e.water, tiers[t].water)),
              (tiers[t].sewage = sanitizeNumber(e.sewage, tiers[t].sewage));
          }),
          renderTariffTable()),
        calcAll(),
        alert("تم استيراد الإعدادات بنجاح.");
    } catch (e) {
      logClientError(e.message, "importSettings"), alert("ملف غير صالح، تعذّر استيراد الإعدادات.");
    }
  }),
    n.readAsText(t),
    (e.target.value = "");
}

function initScrollProgress() {
  const e = document.getElementById("scrollProgress");
  if (!e) return;
  let t = !1;
  function n() {
    const n = window.scrollY,
      r = document.documentElement.scrollHeight - window.innerHeight,
      a = r > 0 ? (n / r) * 100 : 0;
    (e.style.width = Math.min(100, Math.max(0, a)) + "%"), (t = !1);
  }
  window.addEventListener(
    "scroll",
    () => {
      t || (requestAnimationFrame(n), (t = !1));
    },
    { passive: !0 }
  ),
    n();
}

function initFadeInCards() {
  const e = document.querySelectorAll(".fade-in");
  if (!e.length || !("IntersectionObserver" in window)) return;
  e.forEach((e) => e.classList.add("fade-init"));
  const t = new IntersectionObserver((e) => {
    e.forEach((e) => {
      e.isIntersecting && (e.target.classList.add("is-visible"), t.unobserve(e.target));
    });
  }, { threshold: 0.15 });
  e.forEach((e) => t.observe(e));
}

function showInstallToast() {
  const e = document.getElementById("pwaToast");
  e && e.classList.add("show");
}

function hideInstallToast() {
  const e = document.getElementById("pwaToast");
  e && e.classList.remove("show");
}

function installApp() {
  hideInstallToast(),
    deferredInstallPrompt &&
      (deferredInstallPrompt.prompt(),
      deferredInstallPrompt.userChoice.finally(() => {
        deferredInstallPrompt = null;
      }));
}

!(function () {
  const e = loadSettings();
  Array.isArray(e.tariffOverride) &&
    e.tariffOverride.length === tiers.length &&
    e.tariffOverride.forEach((e, t) => {
      (tiers[t].water = sanitizeNumber(e.water, tiers[t].water)),
        (tiers[t].sewage = sanitizeNumber(e.sewage, tiers[t].sewage));
    }),
    renderTariffTable(),
    calcAll(),
    initScrollProgress(),
    initFadeInCards();

  const t = document.getElementById("themeToggle");
  if (t) {
    const e = document.documentElement.getAttribute("data-theme"),
      n = window.matchMedia("(prefers-color-scheme: dark)").matches,
      r = e ? "dark" === e : n;
    t.setAttribute("aria-pressed", String(r));
  }

  const n = document.getElementById("appVersion");
  n && (n.textContent = `${APP_CONFIG.appName} — الإصدار ${APP_CONFIG.version}`);
})();

if ("serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("./service-worker.js").catch((e) => {
      console.warn("تعذر تسجيل Service Worker:", e),
        logClientError(e.message || String(e), "serviceWorker.register");
    });
  });
}

window.addEventListener("beforeinstallprompt", (e) => {
  e.preventDefault(), (deferredInstallPrompt = e), showInstallToast();
});
